1	import {
2	  MessageLikeEventContent_Tags,
3	  type MessageType,
4	  MessageType_Tags,
5	  NotificationEvent_Tags,
6	  type NotificationItem,
7	  TimelineEventType_Tags,
8	} from "@unomed/react-native-matrix-sdk";
9	import { cleanMentions } from "modules/matrix-client/utils";
10	import { MatrixNotificationService } from "modules/push-notifications/service/MatrixNotificationService";
11	
12	type FormattedNotification = {
13	  title: string;
14	  message: string;
15	  room_id: string;
16	};
17	
18	/** Get the decrypted content of an encrypted event*/
19	export const getDecryptedEventContent = async (
20	  roomId: string,
21	  eventId: string,
22	): Promise<string | null> => {
23	  try {
24	    const notificationClient =
25	      MatrixNotificationService.getNotificationClient() ||
26	      (await MatrixNotificationService.ensureNotificationClient());
27	    if (!notificationClient) return null;
28	
29	    const item = await MatrixNotificationService.getNotificationContent(
30	      roomId,
31	      eventId,
32	    );
33	    if (!item) return null;
34	
35	    return getNotificationItemContent(item);
36	  } catch (error) {
37	    console.warn("Failed to get decrypted event content:", error);
38	    return null;
39	  }
40	};
41	
42	const formatMessageType = (messageType: MessageType): string | null => {
43	  if (!messageType) return null;
44	
45	  switch (messageType.tag) {
46	    case MessageType_Tags.Text:
47	    case MessageType_Tags.Emote:
48	    case MessageType_Tags.Notice:
49	      return cleanMentions(messageType.inner.content.body || "") || "Message";
50	    case MessageType_Tags.Image:
51	      return "📷 Image";
52	    case MessageType_Tags.Video:
53	      return "🎥 Video";
54	    case MessageType_Tags.Audio:
55	      return "🎵 Audio";
56	    case MessageType_Tags.File:
57	      return "📎 File";
58	    case MessageType_Tags.Location:
59	      return "📍 Location";
60	    case MessageType_Tags.Gallery:
61	      return "📷 Gallery";
62	    default:
63	      return null;
64	  }
65	};
66	
67	const getNotificationItemContent = (item: NotificationItem): string | null => {
68	  if (item.event.tag !== NotificationEvent_Tags.Timeline) return null;
69	
70	  const eventType = item.event.inner.event.eventType();
71	  if (eventType.tag !== TimelineEventType_Tags.MessageLike) return null;
72	
73	  const content = eventType.inner.content;
74	
75	  switch (content.tag) {
76	    case MessageLikeEventContent_Tags.RoomMessage:
77	      return formatMessageType(content.inner.messageType) || "Message";
78	    case MessageLikeEventContent_Tags.RoomEncrypted:
79	      return null;
80	    case MessageLikeEventContent_Tags.Sticker:
81	      return "🧩 Sticker";
82	    case MessageLikeEventContent_Tags.Poll:
83	      return "📊 Poll";
84	    case MessageLikeEventContent_Tags.ReactionContent:
85	      return "Reacted to a message";
86	    case MessageLikeEventContent_Tags.RoomRedaction:
87	      return "Message deleted";
88	    case MessageLikeEventContent_Tags.CallInvite:
89	    case MessageLikeEventContent_Tags.RtcNotification:
90	      return "Incoming call";
91	    case MessageLikeEventContent_Tags.CallHangup:
92	      return "Call ended";
93	    case MessageLikeEventContent_Tags.KeyVerificationReady:
94	    case MessageLikeEventContent_Tags.KeyVerificationCancel:
95	    case MessageLikeEventContent_Tags.KeyVerificationDone:
96	    case MessageLikeEventContent_Tags.KeyVerificationStart:
97	    case MessageLikeEventContent_Tags.KeyVerificationAccept:
98	    case MessageLikeEventContent_Tags.KeyVerificationKey:
99	    case MessageLikeEventContent_Tags.KeyVerificationMac:
100	      return null;
101	    default:
102	      return null;
103	  }
104	};
105	
106	/** Check if a decrypted notification item is a verification protocol step (not the initial request) */
107	const isNotificationItemVerificationStep = (
108	  item: NotificationItem,
109	): boolean => {
110	  if (item.event.tag !== NotificationEvent_Tags.Timeline) return false;
111	
112	  const eventType = item.event.inner.event.eventType();
113	  if (eventType.tag !== TimelineEventType_Tags.MessageLike) return false;
114	
115	  const { tag } = eventType.inner.content;
116	  return (
117	    tag === MessageLikeEventContent_Tags.KeyVerificationReady ||
118	    tag === MessageLikeEventContent_Tags.KeyVerificationStart ||
119	    tag === MessageLikeEventContent_Tags.KeyVerificationAccept ||
120	    tag === MessageLikeEventContent_Tags.KeyVerificationKey ||
121	    tag === MessageLikeEventContent_Tags.KeyVerificationMac ||
122	    tag === MessageLikeEventContent_Tags.KeyVerificationCancel ||
123	    tag === MessageLikeEventContent_Tags.KeyVerificationDone ||
124	    tag === MessageLikeEventContent_Tags.ReactionContent
125	  );
126	};
127	
128	/** Check if an encrypted event is a verification protocol step (should be suppressed) */
129	export const isDecryptedEventVerificationStep = async (
130	  roomId: string,
131	  eventId: string,
132	): Promise<boolean> => {
133	  try {
134	    const notificationClient =
135	      MatrixNotificationService.getNotificationClient() ||
136	      (await MatrixNotificationService.ensureNotificationClient());
137	    if (!notificationClient) return false;
138	
139	    const item = await MatrixNotificationService.getNotificationContent(
140	      roomId,
